     2	
     3	import java.time.Clock;
     4	import java.time.LocalDate;
     5	import java.time.ZonedDateTime;
     6	import java.util.ArrayList;
     7	import java.util.HashMap;
     8	import java.util.List;
     9	import java.util.Map;
    10	
    11	/**
    12	 * Runs every outgoing message through an ordered chain of rules, then records the result in the
    13	 * {@link MessageLog}. Each rule has a {@link Scope} deciding whether it runs in the current mode.
    14	 */
    15	public class MessageDispatcher {
    16	
    17	    /** A message being processed; rules may block it, rewrite it or add copies. */
    18	    static final class Draft {
    19	        final String originalTo;
    20	        final String originalSubject;
    21	        final String originalBody;
    22	        String to;
    23	        String subject;
    24	        String body;
    25	        boolean blocked;
    26	        final List<Draft> copies = new ArrayList<>();
    27	
    28	        Draft(String to, String subject, String body) {
    29	            this.originalTo = to;
    30	            this.originalSubject = subject;
    31	            this.originalBody = body;
    32	            this.to = to;
    33	            this.subject = subject;
    34	            this.body = body;
    35	        }
    36	    }
    37	
    38	    interface Rule {
    39	        void apply(Draft draft);
    40	    }
    41	
    42	    private record Step(Scope scope, Rule rule) {}
    43	
    44	    private final MessageLog log;
    45	    private final boolean testMode;
    46	    private final List<Step> steps = new ArrayList<>();
    47	
    48	    public MessageDispatcher(AppConfig config, Clock clock, MessageLog log) {
    49	        this.log = log;
    50	        this.testMode = config.testMode();
    51	
    52	        steps.add(new Step(Scope.ALWAYS, d -> d.blocked = !validAddress(d.to)));
    53	        steps.add(new Step(config.quietHours(), new QuietHours(clock, config)));
    54	        steps.add(new Step(config.dailyLimit(), new DailyLimit(clock, config)));
    55	        steps.add(new Step(Scope.TEST_ONLY, MessageDispatcher::redirectToTest));
    56	        steps.add(new Step(config.archiveCopy(), MessageDispatcher::addArchiveCopy));
    57	    }
    58	
    59	    public synchronized void sendEmail(String to, String subject, String body) {
    60	        Draft draft = new Draft(to, subject, body);
    61	        for (Step step : steps) {
    62	            if (!draft.blocked && step.scope().appliesTo(testMode)) {
    63	                step.rule().apply(draft);
    64	            }
    65	        }
    66	        if (draft.blocked) {
    67	            log.add(Message.Channel.EMAIL, draft.originalTo, draft.originalSubject, draft.originalBody,
    68	                    Message.Status.BLOCKED);
    69	            return;
    70	        }
    71	        log.add(Message.Channel.EMAIL, draft.to, draft.subject, draft.body, Message.Status.SENT);
    72	        for (Draft copy : draft.copies) {
    73	            log.add(Message.Channel.EMAIL, copy.to, copy.subject, copy.body, Message.Status.SENT);
    74	        }
    75	    }
    76	
    77	    /** Exactly one '@', something before it, and a domain with a dot that is not at either end. */
    78	    static boolean validAddress(String address) {
    79	        if (address == null || address.chars().anyMatch(Character::isWhitespace)) return false;
    80	        int at = address.indexOf('@');
    81	        if (at < 1 || at != address.lastIndexOf('@')) return false;
    82	        String domain = address.substring(at + 1);
    83	        return domain.indexOf('.') > 0 && !domain.endsWith(".");
    84	    }
    85	
    86	    private static void redirectToTest(Draft d) {
    87	        d.body = "Destinatário original: " + d.to + "\n" + d.body;
    88	        d.subject = "[TESTE] " + d.subject;
    89	        d.to = AppConfig.TEST_ADDRESS;
    90	    }
    91	
    92	    private static void addArchiveCopy(Draft d) {
    93	        d.copies.add(new Draft(AppConfig.ARCHIVE_ADDRESS, "[Cópia] " + d.subject, d.body));
    94	    }
    95	
    96	    private static final class QuietHours implements Rule {
    97	        private final Clock clock;
    98	        private final AppConfig config;
    99	
   100	        QuietHours(Clock clock, AppConfig config) {
   101	            this.clock = clock;
   102	            this.config = config;
   103	        }
   104	
   105	        @Override
   106	        public void apply(Draft d) {
   107	            int hour = ZonedDateTime.now(clock.withZone(config.zone())).getHour();
   108	            int start = config.quietStartHour();
   109	            int end = config.quietEndHour();
   110	            d.blocked = start <= end ? hour >= start && hour < end : hour >= start || hour < end;
   111	        }
   112	    }
   113	
   114	    /** At most N sent messages per guest address per calendar day. */
   115	    private static final class DailyLimit implements Rule {
   116	        private final Clock clock;
   117	        private final AppConfig config;
   118	        private final Map<String, Integer> counts = new HashMap<>();
   119	
   120	        DailyLimit(Clock clock, AppConfig config) {
   121	            this.clock = clock;
   122	            this.config = config;
   123	        }
   124	
   125	        @Override
   126	        public void apply(Draft d) {
   127	            LocalDate today = LocalDate.now(clock.withZone(config.zone()));
   128	            counts.keySet().removeIf(k -> !k.startsWith(today + "|"));
   129	            String key = today + "|" + d.originalTo.toLowerCase();
   130	            int used = counts.getOrDefault(key, 0);
   131	            if (used >= config.maxMessagesPerGuestPerDay()) {
   132	                d.blocked = true;
   133	            } else {
   134	                counts.put(key, used + 1);
   135	            }
   136	        }
   137	    }
   138	}
