     3	/** Where a delivery rule applies. */
     4	public enum Scope {
     5	    ALWAYS, TEST_ONLY, LIVE_ONLY, OFF;
     6	
     7	    public boolean appliesTo(boolean testMode) {
     8	        return switch (this) {
     9	            case ALWAYS -> true;
    10	            case TEST_ONLY -> testMode;
    11	            case LIVE_ONLY -> !testMode;
    12	            case OFF -> false;
    13	        };
    14	    }
