    54	                "true".equalsIgnoreCase(trim(env.apply("HOTEL_TEST_MODE"))),
    55	                scope(env.apply("HOTEL_RULE_ARCHIVE_COPY"), d.archiveCopy),
    56	                scope(env.apply("HOTEL_RULE_QUIET_HOURS"), d.quietHours),
    57	                integer(env.apply("HOTEL_QUIET_START"), d.quietStartHour),
    58	                integer(env.apply("HOTEL_QUIET_END"), d.quietEndHour),
    59	                scope(env.apply("HOTEL_RULE_DAILY_LIMIT"), d.dailyLimit),
    60	                integer(env.apply("HOTEL_DAILY_LIMIT"), d.maxMessagesPerGuestPerDay),
    61	                tz == null || tz.isBlank() ? d.zone : ZoneId.of(tz.trim()));
    62	    }
    63	
    64	    private static String trim(String s) {
    65	        return s == null ? null : s.trim();
    66	    }
    67	
    68	    private static Scope scope(String value, Scope fallback) {
    69	        return value == null || value.isBlank() ? fallback : Scope.valueOf(value.trim().toUpperCase(Locale.ROOT));
    70	    }
