   123	    private static ReservationService.NewReservation parseNew(Context ctx) {
   124	        JsonNode root;
   125	        try {
   126	            root = MAPPER.readTree(ctx.body());
   127	        } catch (Exception e) {
   128	            throw ApiException.invalid("Body is not valid JSON");
   129	        }
   130	        if (root == null || !root.isObject()) {
   131	            throw ApiException.invalid("Body must be a JSON object");
   132	        }
   133	        Integer room = roomNumber(root.get("roomNumber"));
   134	        String name = text(root, "guestName");
   135	        String email = text(root, "guestEmail");
   136	        String cpf = text(root, "guestCpf");
   137	        LocalDate in = date(root, "checkIn");
   138	        LocalDate out = date(root, "checkOut");
   139	        JsonNode g = root.get("guests");
   140	        if (g == null || !g.isIntegralNumber() || !g.canConvertToInt()) {
   141	            throw ApiException.invalid("guests must be an integer");
   142	        }
   143	        RatePlan plan;
   144	        try {
   145	            plan = RatePlan.valueOf(text(root, "ratePlan"));
   146	        } catch (IllegalArgumentException e) {
   147	            throw ApiException.invalid("ratePlan must be STANDARD or NON_REFUNDABLE");
   148	        }
   149	        return new ReservationService.NewReservation(room, name, email, cpf, in, out, g.intValue(), plan);
   150	    }
   151	
   152	    private static Integer roomNumber(JsonNode n) {
   153	        if (n != null && n.isIntegralNumber() && n.canConvertToInt()) return n.intValue();
   154	        if (n != null && n.isTextual() && n.asText().matches("\\d{1,9}")) return Integer.parseInt(n.asText());
   155	        throw ApiException.invalid("roomNumber must be a room number");
   156	    }
   157	
   158	    private static String text(JsonNode root, String field) {
   159	        JsonNode n = root.get(field);
   160	        if (n == null || !n.isTextual() || n.asText().isBlank()) {
   161	            throw ApiException.invalid(field + " is required");
   162	        }
   163	        return n.asText();
   164	    }
   165	
   166	    private static LocalDate date(JsonNode root, String field) {
   167	        String v = text(root, field);
   168	        if (!DAY.matcher(v).matches()) throw ApiException.invalid(field + " must be in the format yyyy-MM-dd");
   169	        try {
   170	            return LocalDate.parse(v);
   171	        } catch (DateTimeParseException e) {
   172	            throw ApiException.invalid(field + " must be in the format yyyy-MM-dd");
   173	        }
   174	    }
   175	}

