    96	    private static final class QuietHours implements Rule {
    97	        private final Clock clock;
    98	        private final AppConfig config;
    99	
   100	        QuietHours(Clock clock, AppConfig config) {
   101	            this.clock = clock;
   102	            this.config = config;
   103	        }
   104	
   105	        @Override
   106	        public void apply(Draft d) {
   107	            int hour = ZonedDateTime.now(clock.withZone(config.zone())).getHour();
   108	            int start = config.quietStartHour();
   109	            int end = config.quietEndHour();
   110	            d.blocked = start <= end ? hour >= start && hour < end : hour >= start || hour < end;
   111	        }
   112	    }
   113	
   114	    /** At most N sent messages per guest address per calendar day. */
   115	    private static final class DailyLimit implements Rule {
   116	        private final Clock clock;
   117	        private final AppConfig config;
   118	        private final Map<String, Integer> counts = new HashMap<>();
   119	
   120	        DailyLimit(Clock clock, AppConfig config) {
   121	            this.clock = clock;
   122	            this.config = config;
   123	        }
   124	
   125	        @Override
   126	        public void apply(Draft d) {
   127	            LocalDate today = LocalDate.now(clock.withZone(config.zone()));
   128	            counts.keySet().removeIf(k -> !k.startsWith(today + "|"));
   129	            String key = today + "|" + d.originalTo.toLowerCase();
   130	            int used = counts.getOrDefault(key, 0);
   131	            if (used >= config.maxMessagesPerGuestPerDay()) {
   132	                d.blocked = true;
   133	            } else {
   134	                counts.put(key, used + 1);
   135	            }
   136	        }
   137	    }
