     1	package br.com.pousadamarealta;
     2	
     3	import br.com.pousadamarealta.Reservation.Status;
     4	import java.time.LocalDate;
     5	import java.util.ArrayList;
     6	import java.util.List;
     7	
     8	public class ReservationService {
     9	    public record NewReservation(Integer roomNumber, String guestName, String guestEmail, String guestCpf,
    10	                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {}
    11	
    12	    private final List<Reservation> reservations = new ArrayList<>();
    13	    private final MessageDispatcher dispatcher;
    14	
    15	    public ReservationService(MessageDispatcher dispatcher) {
    16	        this.dispatcher = dispatcher;
    17	    }
    18	
    19	    public synchronized Reservation create(NewReservation req) {
    20	        if (!req.checkOut().isAfter(req.checkIn())) {
    21	            throw ApiException.invalid("checkOut must be after checkIn");
    22	        }
    23	        if (req.guests() < 1) {
    24	            throw ApiException.invalid("guests must be at least 1");
    25	        }
    26	        Room room = Room.find(req.roomNumber())
    27	                .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Room not found: " + req.roomNumber()));
    28	        if (req.guests() > room.capacity()) {
    29	            throw new ApiException(422, "CAPACITY_EXCEEDED",
    30	                    "Room " + room.number() + " holds at most " + room.capacity() + " guests");
    31	        }
    32	        boolean taken = reservations.stream().anyMatch(r -> r.room.equals(room) && r.active()
    33	                && r.overlaps(req.checkIn(), req.checkOut()));
    34	        if (taken) {
    35	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Room " + room.number() + " is not available");
    36	        }
    37	        Reservation r = new Reservation(reservations.size() + 1L, room, req.guestName(), req.guestEmail(),
    38	                req.guestCpf(), req.checkIn(), req.checkOut(), req.guests(), req.ratePlan());
    39	        reservations.add(r);
    40	        return r;
    41	    }
    42	
    43	    public synchronized Reservation get(long id) {
    44	        if (id < 1 || id > reservations.size()) {
    45	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found: " + id);
    46	        }
    47	        return reservations.get((int) id - 1);
    48	    }
    49	
    50	    public synchronized Reservation confirm(long id) {
    51	        Reservation r = require(id, Status.PENDING, "Only pending reservations can be confirmed");
    52	        r.status = Status.CONFIRMED;
    53	        r.amountPaid = r.total;
    54	        dispatcher.sendEmail(r.guestEmail, "Reserva confirmada - Pousada Maré Alta", confirmationBody(r));
    55	        return r;
    56	    }
    57	
    58	    public synchronized Reservation cancel(long id) {
    59	        Reservation r = require(id, "Only pending or confirmed reservations can be cancelled",
    60	                Status.PENDING, Status.CONFIRMED);
    61	        r.refund = r.ratePlan.refundable() ? r.amountPaid : Money.ZERO;
    62	        r.status = Status.CANCELLED;
    63	        return r;
    64	    }
    65	
    66	    public synchronized Reservation checkIn(long id) {
    67	        Reservation r = require(id, Status.CONFIRMED, "Only confirmed reservations can check in");
    68	        r.status = Status.CHECKED_IN;
    69	        return r;
    70	    }
    71	
    72	    public synchronized Reservation checkOut(long id) {
    73	        Reservation r = require(id, Status.CHECKED_IN, "Only checked-in reservations can check out");
    74	        r.status = Status.CHECKED_OUT;
    75	        return r;
    76	    }
    77	
    78	    /** Receipt (second copy); only for paid reservations. */
    79	    public synchronized Reservation forDocument(long id) {
    80	        Reservation r = get(id);
    81	        if (!r.paid()) {
    82	            throw ApiException.notAllowed("Receipt is only available for paid reservations");
    83	        }
    84	        return r;
    85	    }
    86	
    87	    public synchronized List<Reservation> snapshot() {
    88	        return List.copyOf(reservations);
    89	    }
    90	
    91	    private Reservation require(long id, Status expected, String message) {
    92	        return require(id, message, expected);
    93	    }
    94	
    95	    private Reservation require(long id, String message, Status... allowed) {
    96	        Reservation r = get(id);
    97	        for (Status s : allowed) {
    98	            if (r.status == s) return r;
    99	        }
   100	        throw ApiException.notAllowed(message);
   101	    }
   102	
   103	    static String confirmationBody(Reservation r) {
   104	        return "Olá, " + r.guestName + "!\n\n"
   105	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
   106	                + Receipt.text(r) + "\n\n"
   107	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   108	                + "Até breve!";
   109	    }
   110	}
   111	package br.com.pousadamarealta;
   112	
   113	import java.math.BigDecimal;
   114	import java.time.LocalDate;
   115	import java.time.Month;
   116	
   117	public final class Pricing {
   118	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
   119	
   120	    private Pricing() {}
   121	
   122	    /** High season: Dec 15 to end of February, and all of July. */
   123	    public static boolean highSeason(LocalDate night) {
   124	        Month m = night.getMonth();
   125	        return m == Month.JANUARY || m == Month.FEBRUARY || m == Month.JULY
   126	                || (m == Month.DECEMBER && night.getDayOfMonth() >= 15);
   127	    }
   128	
   129	    public static BigDecimal nightPrice(Room room, LocalDate night) {
   130	        BigDecimal base = room.nightlyRate();
   131	        return highSeason(night) ? Money.round(base.multiply(HIGH_SEASON_FACTOR)) : Money.round(base);
   132	    }
   133	
   134	    public static BigDecimal subtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
   135	        BigDecimal sum = Money.ZERO;
   136	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
   137	            sum = Money.round(sum.add(nightPrice(room, d)));
   138	        }
   139	        return sum;
   140	    }
   141	}
